public class TokenBucket {
    private final long capacity;
    private final double refillRatePerNano;
    private double tokens;
    private long lastRefillTime;

    public TokenBucket(long capacity, double refillRatePerSecond) {
        this.capacity = capacity;
        this.refillRatePerNano = refillRatePerSecond / 1e9;
        this.tokens = capacity;
        this.lastRefillTime = System.nanoTime();
    }

    // BUG: Synchronized keyword creates severe lock contention and thread parking across cores
    public synchronized boolean tryConsume(int requested) {
        long now = System.nanoTime();
        double elapsed = now - lastRefillTime;
        tokens = Math.min(capacity, tokens + elapsed * refillRatePerNano);
        lastRefillTime = now;
        if (tokens >= requested) {
            tokens -= requested;
            return True;
        }
        return false;
    }
}

